def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []

    # Find bounding boxes of connected 3-regions; embedded 2s are holes
    # and are handled by checking whether they fall inside a region's box.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 3 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            boxes.append((min(x for x,y in cells), max(x for x,y in cells),
                          min(y for x,y in cells), max(y for x,y in cells)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if not any(r0 <= r <= r1 and c0 <= c <= c1
                       for r0, r1, c0, c1 in boxes):
                continue
            for rr in range(max(0, r-1), min(h, r+2)):
                for cc in range(max(0, c-1), min(w, c+2)):
                    if grid[rr][cc] != 2:
                        out[rr][cc] = 1
    return out
