def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []

    # Get bounding boxes of each connected 3-region.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 3 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            boxes.append((min(x for x, y in cells), max(x for x, y in cells),
                          min(y for x, y in cells), max(y for x, y in cells)))

    seeds = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1
                                       for r0, r1, c0, c1 in boxes):
                seeds.add((r, c))

    for r, c in seeds:
        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                out[rr][cc] = 1

    # The seed markers remain 2; other markers in a painted patch are overwritten.
    for r, c in seeds:
        out[r][c] = 2
    return out
